       need to change to reskin the whole deck). Lock them to a small,
       curated set of presets in that skill's own references/themes.md —
       never let a caller pass an arbitrary hex value straight through. */
    --ink:#141414;
    --paper:#fafaf8;
    --accent:#2b5fff;

    /* ============ type tokens ============
       System stacks by default so the engine has zero network
       dependency. A specific skill may swap in webfonts here. */
    --font-display:-apple-system,"SF Pro Display","Helvetica Neue",Arial,sans-serif;
    --font-body:-apple-system,"SF Pro Text","Helvetica Neue",Arial,sans-serif;
